<script lang="ts">
  import Lenis from 'lenis';
  import 'lenis/dist/lenis.css';
  import { onMount } from 'svelte';
  import { getCountdownState } from '$lib/data/countdown';
  import { ArrowDown01Icon, ArrowUpRight01Icon } from '$lib/icons';

  const event = {
    date: 'Thursday, 3 September 2026',
    shortDate: '03 / Sept / 26',
    time: '11:00 AM — 12:30 PM',
    venue: 'Rivervale Primary School',
  };

  const storyPhotos = [
    {
      src: '/images/story-01.webp',
      alt: 'Graduates gathered with a teacher during a previous Teachers’ Day visit',
      x: -31,
      y: -18,
      rotation: -7,
      scale: 0.88,
