    {
      src: '/images/story-03.webp',
      alt: 'Former students reconnecting with members of the school community',
      x: 27,
      y: -20,
      rotation: 7,
      scale: 0.86,
      z: 4,
    },
    {
      src: '/images/story-04.webp',
      alt: 'Graduates posing with a teacher in the school canteen',
      x: 32,
      y: 8,
      rotation: -5,
      scale: 0.9,
      z: 2,
    },
    {
      src: '/images/story-05.webp',
      alt: 'Teachers and former students talking together during a school visit',
      x: 17,
      y: 26,
      rotation: 4,
      scale: 0.82,
      z: 4,
    },
    {
      src: '/images/story-06.webp',
      alt: 'A teacher and graduate taking a photo together',
      x: -28,
      y: 22,
      rotation: 7,
      scale: 0.84,
      z: 2,
    },
    {
      src: '/images/story-07.webp',
      alt: 'A large group of graduates gathered for a photo in the school canteen',
      x: 0,
      y: 0,
      rotation: -2,
      scale: 0.7,
      z: 3,
      focus: true,
    },
  ];

  const moments = [
    {
      number: '01',
      title: 'Arrive',
      copy: 'Enter the Turnstile via Gate 2',
      imageClass: 'photo-arrive',
      alt: 'The Turnstile entrance at Gate 2 of Rivervale Primary School',
    },
    {
      number: '02',
      title: 'Check-in',
      copy: 'Approach our friendly receptionists at the Kindness Corner to check-in',
      imageClass: 'photo-checkin',
      alt: 'RIVA volunteers welcoming visitors at the Kindness Corner',
    },
    {
      number: '03',
      title: 'Reconnect',
      copy: 'Meet your former teachers, old friends and fellow Riverlites who remember you.',
      imageClass: 'photo-reunion',
      alt: 'Former teachers and Riverlites reconnecting during a school visit',
    },
  ];

  const teacherNames = [
    'MR FIRDAUS',
    'MR ZAKIR',
    'MR RAZIF',
    'MDM CHAN',
    'MS FRONIA',
    'MR KHAIR',
    'MR HO',
    'MS SAKINA',
    'MR RIDUAN',
    'MR SEAH',
    'MDM CHIAH',
    'MR LIM',
    'MR YEE',
    'MRS THOMAS',
    'MDM LI',
    'AND MANY MORE TEACHERS',
  ];

  const tickerItems = [
    { text: 'COME BACK TO RIVPS', emoji: '💌' },
    { text: 'REGISTER YOUR VISIT', emoji: '💙' },
    { text: '3 SEPTEMBER 2026', emoji: '👩‍🏫' },
    { text: 'COME BACK TO RIVPS', emoji: '💌' },
    { text: 'REGISTER YOUR VISIT', emoji: '💙' },
    { text: '3 SEPTEMBER 2026', emoji: '👩‍🏫' },
  ];

  let storySection = $state<HTMLElement | null>(null);
  let storyProgress = $state(0);
  let heroProgress = $state(0);
  let motionReady = $state(false);
  let prefersReducedMotion = $state(false);
  let countdown = $state(getCountdownState());

  const clamp = (value: number) => Math.min(1, Math.max(0, value));

  onMount(() => {
    const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    const lenis = motionQuery.matches
      ? null
      : new Lenis({
          anchors: {
            duration: 1.45,
            offset: 0,
          },
          autoRaf: true,
          duration: 1.1,
          smoothWheel: true,
          stopInertiaOnNavigate: true,
        });
    let animationFrame = 0;
    const countdownInterval = window.setInterval(() => {
      countdown = getCountdownState();
    }, 1_000);

    const updateMotionPreference = () => {
      prefersReducedMotion = motionQuery.matches;
    };

    const updateScrollState = () => {
      heroProgress = prefersReducedMotion
        ? 0
        : clamp(window.scrollY / Math.max(window.innerHeight * 0.85, 1));

      if (storySection && !prefersReducedMotion) {
        const bounds = storySection.getBoundingClientRect();
        const travel = Math.max(bounds.height - window.innerHeight, 1);
        storyProgress = clamp(-bounds.top / travel);
      } else {
        storyProgress = 0.5;
      }

      animationFrame = 0;
    };

    const requestScrollUpdate = () => {
      if (!animationFrame) {
        animationFrame = window.requestAnimationFrame(updateScrollState);
      }
    };

    updateMotionPreference();
    updateScrollState();
    motionReady = true;

    const revealObserver = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add('is-visible');
            revealObserver.unobserve(entry.target);
          }
        }
      },
      { threshold: 0.16, rootMargin: '0px 0px -8% 0px' },
    );

    const revealElements = document.querySelectorAll<HTMLElement>(
      '[data-reveal], [data-teacher-reveal]',
    );
    for (const element of revealElements) {
      revealObserver.observe(element);
    }

    window.addEventListener('scroll', requestScrollUpdate, { passive: true });
    window.addEventListener('resize', requestScrollUpdate);
    motionQuery.addEventListener('change', updateMotionPreference);
    motionQuery.addEventListener('change', requestScrollUpdate);

    return () => {
      if (animationFrame) window.cancelAnimationFrame(animationFrame);
      revealObserver.disconnect();
      window.removeEventListener('scroll', requestScrollUpdate);
      window.removeEventListener('resize', requestScrollUpdate);
      motionQuery.removeEventListener('change', updateMotionPreference);
      motionQuery.removeEventListener('change', requestScrollUpdate);
      window.clearInterval(countdownInterval);
      lenis?.destroy();
    };
  });
</script>

