    display: flex;
    align-items: center;
    gap: clamp(0.9rem, 1.6vw, 1.5rem);
    text-transform: uppercase;
  }

  .hero-countdown > p {
    max-width: none;
    margin: 0;
    color: rgba(255, 255, 255, 0.7);
    font-size: clamp(0.58rem, 0.72vw, 0.68rem);
    font-weight: 680;
    line-height: 1.2;
    letter-spacing: 0.015em;
    white-space: nowrap;
  }

  .hero-countdown > strong {
    font-size: clamp(0.78rem, 0.95vw, 0.9rem);
    font-weight: 650;
  }

  .hero-countdown-units {
    padding-left: clamp(0.9rem, 1.6vw, 1.5rem);
    display: flex;
    gap: clamp(0.75rem, 1.4vw, 1.25rem);
    border-left: 1px solid rgba(255, 255, 255, 0.42);
  }

  .hero-countdown-units > span {
    display: inline-flex;
    align-items: baseline;
    gap: 0.22rem;
  }

  .hero-countdown-units strong {
    min-width: 2ch;
    font-variant-numeric: tabular-nums;
    font-size: clamp(1.05rem, 1.55vw, 1.4rem);
    font-weight: 560;
    line-height: 1;
    letter-spacing: -0.045em;
  }

  .hero-countdown-units small {
    color: rgba(255, 255, 255, 0.58);
    font-size: 0.52rem;
    font-weight: 700;
  }

  .hero-details {
    display: grid;
    grid-template-columns: minmax(12rem, 1fr) minmax(12rem, 1fr) auto;
    align-items: end;
    gap: clamp(1.5rem, 4vw, 5rem);
    border-top: 1px solid rgba(255, 255, 255, 0.42);
    padding-top: 1rem;
  }

  .hero-details p,
  .hero-details time,
  .hero-details span {
    display: block;
    margin: 0;
  }

  .hero-details p {
    margin-bottom: 0.3rem;
  }

  .hero-details time,
  .hero-details div > span {
    color: rgba(255, 255, 255, 0.72);
    text-transform: none;
    font-weight: 450;
  }

  .action-link {
    min-width: min(100%, 14.5rem);
    min-height: 3.7rem;
    padding: 0 1.05rem;
    display: inline-flex;
    align-items: center;
    justify-content: space-between;
    gap: 2rem;
    border: 1px solid currentColor;
    text-transform: uppercase;
    font-size: 0.74rem;
    font-weight: 700;
    letter-spacing: -0.01em;
    transition:
      color 240ms ease,
      background 240ms ease,
      transform 240ms ease;
  }

  .action-link:hover {
    transform: translateY(-2px);
  }

  .action-link:focus-visible,
  .scroll-cue:focus-visible,
  .registration-footer a:focus-visible {
    outline: 2px solid #fff;
    outline-offset: 4px;
  }

  .action-link--light:hover {
    border-color: var(--red);
    background: var(--red);
    color: #fff;
  }

  .scroll-cue {
    position: absolute;
    z-index: 2;
    top: 48%;
    right: clamp(1.25rem, 2.8vw, 3rem);
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.7rem;
    text-transform: uppercase;
    font-size: 0.64rem;
    letter-spacing: 0.08em;
  }

  .scroll-cue > span:first-child {
    writing-mode: vertical-rl;
  }

  .section-label {
    grid-column: 1 / span 3;
    margin: 0;
    color: var(--muted);
    font-size: clamp(0.73rem, 1vw, 0.9rem);
    letter-spacing: -0.02em;
  }

  .section-label::before {
    content: '';
    display: inline-block;
    width: 0.42rem;
    height: 0.42rem;
    margin-right: 0.75rem;
    background: var(--red);
  }

  .details-intro h2,
  .moments > h2 {
    margin: 0;
    font-size: clamp(3.7rem, 7.25vw, 7.2rem);
    line-height: 0.94;
    letter-spacing: -0.068em;
    font-weight: 520;
    text-wrap: balance;
  }

  .story {
    position: relative;
    height: 300svh;
  }

  .story-sticky {
    position: sticky;
    top: 0;
    height: 100svh;
    overflow: hidden;
    isolation: isolate;
  }

  .story-line {
    position: absolute;
    z-index: 3;
    width: max-content;
    display: flex;
    gap: 10vw;
    white-space: nowrap;
    font-size: clamp(7rem, 15vw, 15rem);
    line-height: 0.78;
    letter-spacing: -0.08em;
    font-weight: 510;
    pointer-events: none;
    will-change: left;
  }

  .story-line--one {
    top: 4vh;
    left: var(--story-left);
  }

  .story-line--two {
    z-index: 1;
    bottom: 4vh;
    left: var(--story-right);
    color: #d7d7d2;
  }

  .story-photo {
    position: absolute;
    top: 50%;
    left: 50%;
    z-index: var(--photo-z);
    width: clamp(9rem, 22vw, 21rem);
    aspect-ratio: 1.5;
    overflow: hidden;
    margin: 0;
    background: #141414;
    opacity: var(--photo-opacity);
    transform: translate(calc(-50% + var(--photo-x)), calc(-50% + var(--photo-y)))
      rotate(var(--photo-rotate)) scale(var(--photo-scale));
    box-shadow: 0 1.25rem 4.5rem rgba(0, 0, 0, 0.5);
    will-change: transform, opacity;
  }

  .story-collage {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  .story-photo img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    filter: brightness(0.78) saturate(0.86);
  }

  .story-photo--focus {
    z-index: 10;
    width: clamp(19rem, 48vw, 48rem);
    box-shadow: 0 2rem 8rem rgba(0, 0, 0, 0.65);
  }

  .teachers {
    min-height: 100svh;
    padding: clamp(5rem, 12vh, 8rem) clamp(1.25rem, 3vw, 4rem);
    display: grid;
    grid-template-rows: auto 1fr;
    align-items: center;
    gap: clamp(3rem, 8vh, 7rem);
    overflow: hidden;
    background: #000;
  }

  .teachers-label {
    margin: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 1rem;
    color: #8b8b89;
    text-transform: uppercase;
    font-size: clamp(0.72rem, 1vw, 0.9rem);
    letter-spacing: 0.01em;
  }

  .teachers-label span {
    width: 0.44rem;
    height: 0.44rem;
    background: var(--red);
  }

  .teachers h2 {
    width: 100%;
    max-width: 96rem;
    margin: 0 auto;
    align-self: start;
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 0.14em 0.18em;
    color: #f5f5f2;
    text-align: center;
    text-transform: uppercase;
    font-size: clamp(2.25rem, 3.65vw, 4.7rem);
    line-height: 1.18;
    letter-spacing: -0.045em;
    font-weight: 520;
    text-wrap: balance;
    perspective: 1000px;
  }

  .teachers h2 .teacher-name {
    display: inline-flex;
    align-items: baseline;
    gap: 0.18em;
    white-space: nowrap;
    transform-style: preserve-3d;
  }

  .teachers h2 .teacher-name--final {
    flex-basis: 100%;
    justify-content: center;
    white-space: normal;
  }

  .teachers h2 .teacher-name--final b {
    display: none;
  }

  .teachers h2 b {
    color: #555;
    font-weight: inherit;
  }

  .breakthrough {
    position: relative;
    min-height: 100svh;
    overflow: hidden;
    display: flex;
    align-items: flex-end;
    isolation: isolate;
  }

  .breakthrough-media,
  .breakthrough-overlay {
    position: absolute;
    inset: 0;
    z-index: -2;
  }

  .breakthrough-media .photo-surface {
    background-position: 50% center;
    filter: saturate(0.82) contrast(1.04);
  }

  .breakthrough-overlay {
    z-index: -1;
    background:
      radial-gradient(
        circle at 50% 35%,
        transparent 0%,
        rgba(0, 0, 0, 0.12) 45%,
        rgba(0, 0, 0, 0.72) 100%
      ),
      linear-gradient(180deg, rgba(0, 0, 0, 0.18) 0%, rgba(0, 0, 0, 0.2) 38%, #050505 100%);
  }

  .countdown-panel {
    width: 100%;
    padding: clamp(7rem, 17vh, 13rem) clamp(1.25rem, 2.8vw, 3rem) clamp(2rem, 4vw, 4rem);
    background: linear-gradient(180deg, transparent 0%, rgba(5, 5, 5, 0.52) 34%, #050505 100%);
    text-align: left;
  }

  .countdown-meta {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 2rem;
  }

  .countdown-eyebrow,
  .countdown-deadline {
    margin: 0;
  }

  .countdown-eyebrow {
    font-size: clamp(1rem, 1.45vw, 1.35rem);
    font-weight: 620;
    letter-spacing: -0.025em;
  }

  .countdown-deadline {
    margin-top: 0.55rem;
    color: rgba(255, 255, 255, 0.68);
    font-size: clamp(0.76rem, 0.9vw, 0.88rem);
  }

  .countdown-grid {
    margin-top: clamp(2.25rem, 4vw, 4rem);
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: clamp(1rem, 2.4vw, 3rem);
  }

  .countdown-grid > div {
    min-width: 0;
    display: flex;
    align-items: flex-end;
    gap: clamp(0.55rem, 1vw, 1rem);
  }

  .countdown-grid strong,
  .countdown-grid span {
    display: block;
  }

  .countdown-grid strong {
    font-variant-numeric: tabular-nums;
    font-size: clamp(5.4rem, 10.8vw, 12.5rem);
    line-height: 0.72;
    letter-spacing: -0.09em;
    font-weight: 510;
  }

  .countdown-grid span {
    margin-bottom: 0.6rem;
    color: rgba(255, 255, 255, 0.82);
    text-transform: lowercase;
    font-size: clamp(0.68rem, 0.9vw, 0.84rem);
    font-weight: 680;
  }

  .countdown-complete {
    margin: clamp(3rem, 6vw, 5rem) 0;
    font-size: clamp(6rem, 17vw, 17rem);
    line-height: 0.76;
    letter-spacing: -0.09em;
    font-weight: 510;
  }

  .action-link--glass {
    min-width: 14rem;
    flex: 0 0 auto;
    background: rgba(4, 4, 4, 0.52);
    backdrop-filter: blur(0.5rem);
  }

  .action-link--glass:hover {
    border-color: var(--red);
    background: var(--red);
    color: #fff;
  }

  .details {
    padding-block: clamp(8rem, 14vw, 13rem);
    display: grid;
    grid-template-columns: repeat(12, minmax(0, 1fr));
    gap: 1rem;
  }

  .details-intro {
    grid-column: 5 / -1;
  }

  .details-intro h2 {
    max-width: 12ch;
  }

  .details-intro > p {
    max-width: 40rem;
    margin: clamp(2.5rem, 5vw, 5rem) 0 0;
    color: #a8a8a4;
    font-size: clamp(1rem, 1.45vw, 1.3rem);
    line-height: 1.45;
  }

  .detail-list {
    grid-column: 1 / -1;
    margin-top: clamp(6rem, 11vw, 10rem);
    border-top: 1px solid var(--line);
  }

  .detail-list article {
    min-height: 14rem;
    padding-block: 2.5rem;
    display: grid;
    grid-template-columns: 1fr 3fr 4fr;
    gap: 1rem;
    border-bottom: 1px solid var(--line);
  }

  .detail-list article > span {
    color: #747471;
    font-size: 0.8rem;
  }

  .detail-list h3,
  .detail-list p {
    margin: 0;
  }

  .detail-list h3 {
    font-size: clamp(2.2rem, 4vw, 4.4rem);
    line-height: 0.95;
    letter-spacing: -0.06em;
    font-weight: 520;
  }

  .detail-list p {
    max-width: 34rem;
    color: #aaa9a5;
    font-size: clamp(1rem, 1.3vw, 1.2rem);
    line-height: 1.5;
  }

  .detail-list p a {
    color: #f5f5f2;
    text-decoration: underline;
    text-underline-offset: 0.2em;
  }

  .moments {
    padding-block: clamp(5rem, 10vw, 9rem) clamp(8rem, 14vw, 13rem);
  }

  .moments > h2 {
    margin: clamp(3rem, 6vw, 5rem) 0 clamp(6rem, 10vw, 10rem);
    font-size: clamp(4rem, 8.3vw, 8rem);
  }

  .moment-card {
    min-height: 32rem;
    padding-block: clamp(2.5rem, 5vw, 5rem);
    display: grid;
    grid-template-columns: 1fr 1.15fr;
    gap: clamp(2rem, 7vw, 8rem);
    align-items: center;
    border-top: 1px solid var(--line);
  }

  .moment-card:last-child {
    border-bottom: 1px solid var(--line);
  }

  .moment-meta {
    display: grid;
    grid-template-columns: 5rem 1fr;
    gap: 1rem;
  }

  .moment-meta > span {
    color: #777773;
    font-size: 0.8rem;
  }

  .moment-meta h3,
  .moment-meta p {
    margin: 0;
  }

  .moment-meta h3 {
    margin-bottom: 1rem;
    font-size: clamp(2.8rem, 5vw, 5.2rem);
    line-height: 0.92;
    letter-spacing: -0.065em;
    font-weight: 520;
  }

  .moment-meta p {
    max-width: 25rem;
    color: #aaa9a5;
    font-size: clamp(0.95rem, 1.2vw, 1.1rem);
    line-height: 1.45;
  }

  .moment-image {
    aspect-ratio: 1.55;
    overflow: hidden;
  }

  .moment-image .photo-surface {
    filter: saturate(0.82) brightness(0.84);
    transition:
      transform 900ms cubic-bezier(0.16, 1, 0.3, 1),
      filter 500ms ease;
  }

  .moment-card:hover .moment-image .photo-surface {
    transform: scale(1.035);
    filter: saturate(1) brightness(0.93);
  }

  .registration {
    background: var(--paper);
    color: var(--ink);
  }

  .registration-ticker {
    overflow: hidden;
    border-bottom: 1px solid rgba(0, 0, 0, 0.22);
  }

  .registration-ticker > div {
    width: max-content;
    padding-block: 0.8rem;
    display: flex;
    gap: 2rem;
    animation: ticker 28s linear infinite;
    font-size: clamp(2.4rem, 4.6vw, 5rem);
    line-height: 0.9;
    letter-spacing: -0.065em;
    font-weight: 540;
    text-transform: uppercase;
  }

  .registration-ticker span {
    display: inline-flex;
    align-items: center;
    gap: 2rem;
  }

  .registration-ticker b {
    font-family: 'Apple Color Emoji', 'Segoe UI Emoji', 'Noto Color Emoji', sans-serif;
    font-size: 0.62em;
    font-weight: 400;
    letter-spacing: 0;
  }

  .registration-layout {
    min-height: 96svh;
    padding: clamp(5rem, 9vw, 9rem) clamp(1.25rem, 2.8vw, 3rem);
    display: grid;
    grid-template-columns: repeat(12, minmax(0, 1fr));
    align-content: center;
    gap: 1rem;
  }

  .section-label--dark {
    grid-column: 1 / span 3;
    color: #595955;
  }

  .registration-copy {
    grid-column: 5 / -1;
  }

  .registration-copy h2 {
    max-width: 10ch;
    margin: 0;
    font-size: clamp(4.5rem, 9vw, 9.3rem);
    line-height: 0.84;
    letter-spacing: -0.08em;
    font-weight: 530;
  }

  .registration-copy > p {
    max-width: 43rem;
    margin: clamp(2.5rem, 5vw, 4.5rem) 0 2rem;
    color: #4f4f4b;
    font-size: clamp(1rem, 1.4vw, 1.25rem);
    line-height: 1.45;
  }

  .action-link--dark {
    min-width: min(100%, 18rem);
  }

  .action-link--dark:hover {
    border-color: var(--red);
    background: var(--red);
    color: #fff;
  }

  .registration-footer {
    margin-inline: clamp(1.25rem, 2.8vw, 3rem);
    padding-block: 1.25rem 1.8rem;
    display: grid;
    grid-template-columns: 1fr auto auto;
    gap: 2rem;
    border-top: 1px solid rgba(0, 0, 0, 0.24);
    text-transform: uppercase;
    font-size: 0.68rem;
    font-weight: 650;
  }

  .registration-footer p {
    margin: 0;
  }

  .registration-footer a {
    border-bottom: 1px solid currentColor;
  }

  .motion-ready [data-reveal] {
    opacity: 0;
    transform: translateY(2.5rem);
    transition:
      opacity 850ms cubic-bezier(0.16, 1, 0.3, 1),
      transform 850ms cubic-bezier(0.16, 1, 0.3, 1);
  }

  .motion-ready [data-reveal]:global(.is-visible) {
    opacity: 1;
    transform: translateY(0);
  }

  .motion-ready [data-teacher-reveal] .teacher-name {
    opacity: 0;
    transform: translate3d(var(--teacher-x), var(--teacher-y), var(--teacher-z))
      rotateX(var(--teacher-rx));
    transition:
      opacity 1.15s cubic-bezier(0.16, 1, 0.3, 1),
      transform 1.35s cubic-bezier(0.16, 1, 0.3, 1);
    transition-delay: var(--teacher-delay);
    will-change: opacity, transform;
  }

  .motion-ready [data-teacher-reveal]:global(.is-visible) .teacher-name {
    opacity: 1;
    transform: translate3d(0, 0, 0) rotateX(0);
  }

  @keyframes ticker {
    to {
      transform: translateX(-50%);
    }
  }

  @media (max-width: 900px) {
    .hero h1 {
      font-size: clamp(3.2rem, 9.2vw, 5.6rem);
    }

    .hero-details {
      grid-template-columns: 1fr 1fr;
    }

    .hero-details .action-link {
      grid-column: 1 / -1;
    }

    .section-label,
    .details-intro,
    .section-label--dark,
    .registration-copy {
      grid-column: 1 / -1;
    }

    .story {
      height: 240svh;
    }

    .story-line {
      font-size: clamp(6rem, 24vw, 11rem);
    }

    .story-photo--focus {
      width: min(78vw, 36rem);
    }

    .details {
      grid-template-columns: 1fr;
    }

    .detail-list {
      grid-column: 1;
    }

    .detail-list article {
      grid-template-columns: 3rem 1fr;
      min-height: 0;
    }

    .detail-list article p {
      grid-column: 2;
    }

    .moment-card {
      grid-template-columns: 1fr;
      gap: 3rem;
    }

    .moment-image {
      order: -1;
    }

    .registration-layout {
      grid-template-columns: 1fr;
      gap: 3rem;
    }
  }

  @media (max-width: 600px) {
    .site-header {
      padding: 0.85rem 1rem;
    }

    .site-header nav {
      width: 100%;
    }

    .site-header a {
      min-width: 0;
      min-height: 3.4rem;
      padding-inline: 0.65rem;
      flex: 1 1 0;
      justify-content: center;
      gap: 0.45rem;
      font-size: clamp(0.55rem, 2.65vw, 0.65rem);
      text-align: center;
    }

    .site-nav-index {
      display: none;
    }

    .hero-grid {
      gap: 1rem;
    }

    .hero h1 {
      max-width: none;
      font-size: clamp(1.95rem, 9vw, 3.6rem);
      line-height: 0.9;
    }

    .hero-countdown {
      margin-top: 1rem;
      display: block;
    }

    .hero-countdown > p {
      max-width: none;
      margin-bottom: 0.65rem;
    }

    .hero-countdown-units {
      padding-left: 0;
      gap: clamp(0.65rem, 4vw, 1rem);
      border-left: 0;
    }

    .hero-countdown-units strong {
      font-size: clamp(1rem, 4.8vw, 1.3rem);
    }

    .hero-details {
      grid-template-columns: 1fr;
      gap: 1rem;
    }

    .hero-details > div {
      padding-bottom: 0.85rem;
      border-bottom: 1px solid rgba(255, 255, 255, 0.25);
    }

    .hero-details .action-link {
      grid-column: 1;
    }

    .scroll-cue {
      display: none;
    }

    .details-intro h2,
    .moments > h2 {
      font-size: clamp(3.3rem, 14vw, 5rem);
    }

    .teachers {
      min-height: 92svh;
      padding-block: 5rem;
      gap: 3.5rem;
    }

    .teachers h2 {
      gap: 0.2em 0.25em;
      font-size: clamp(1.35rem, 5.8vw, 2.45rem);
      line-height: 1.18;
    }

    .story-photo {
      width: clamp(7rem, 36vw, 10rem);
    }

    .story-photo--focus {
      width: min(82vw, 32rem);
    }

    .breakthrough {
      min-height: 100svh;
    }

    .breakthrough-media .photo-surface {
      background-position: 55% center;
    }

    .countdown-panel {
      padding-inline: 1rem;
    }

    .countdown-meta {
      align-items: flex-start;
      flex-direction: column;
    }

    .countdown-meta .action-link {
      width: 100%;
    }

    .countdown-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      row-gap: 2.5rem;
    }

    .countdown-grid strong {
      font-size: clamp(4.8rem, 22vw, 7rem);
    }

    .details {
      padding-block: 7rem;
    }

    .detail-list {
      margin-top: 5rem;
    }

    .detail-list article {
      grid-template-columns: 2.2rem 1fr;
    }

    .moment-card {
      min-height: 0;
    }

    .moment-meta {
      grid-template-columns: 2.2rem 1fr;
    }

    .registration-copy h2 {
      font-size: clamp(4rem, 18vw, 6.2rem);
    }

    .registration-footer {
      grid-template-columns: 1fr;
      gap: 0.6rem;
    }

    .registration-footer a {
      justify-self: start;
      margin-top: 1rem;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    :global(html) {
      scroll-behavior: auto;
    }

    .hero-media .photo-surface,
    .story-line,
    .moment-image .photo-surface,
    .action-link,
    .motion-ready [data-reveal],
    .motion-ready [data-teacher-reveal] .teacher-name {
